typedef unsigned long u_long;
typedef unsigned int u_int;
typedef unsigned long u_long128 __attribute__((mode(TI)));

enum {
    SCE_GS_PSMCT32 = 0,
    SCE_GS_PSMCT24 = 1,
    SCE_GS_PSMCT16 = 2,
    SCE_GS_PSMCT16S = 10,
    SCE_GS_PSMT8 = 19,
    SCE_GS_PSMT4 = 20,
    SCE_GS_PSMT8H = 27,
    SCE_GS_PSMT4HL = 36,
    SCE_GS_PSMT4HH = 44,
    SCE_GS_PSMZ32 = 48,
    SCE_GS_PSMZ24 = 49,
    SCE_GS_PSMZ16 = 50,
    SCE_GS_PSMZ16S = 58,
    SCE_DMA_ID_REFE = 0,
    SCE_DMA_ID_CNT = 1,
    SCE_DMA_ID_REF = 3,
    SCE_DMA_ID_RET = 6,
    SCE_GIF_IMAGE = 2,
    SCE_GS_TRXPOS = 0x51,
    SCE_GS_TRXREG = 0x52,
    SCE_GS_TRXDIR = 0x53
};

#define SCE_DMA_SET_TAG(qwc, pce, id, irq, addr, spr) \
    ((u_long)(qwc) | ((u_long)(pce) << 26) | ((u_long)(id) << 28) | \
     ((u_long)(irq) << 31) | ((u_long)(addr) << 32) | ((u_long)(spr) << 63))
#define SCE_GIF_SET_TAG(nloop, eop, pre, prim, flg, nreg) \
    ((u_long)(nloop) | ((u_long)(eop) << 15) | ((u_long)(pre) << 46) | \
     ((u_long)(prim) << 47) | ((u_long)(flg) << 58) | ((u_long)(nreg) << 60))
#define SCE_GS_SET_TRXREG(rrw, rrh) ((u_long)(rrw) | ((u_long)(rrh) << 32))
#define SCE_GS_SET_TRXPOS(ssax, ssay, dsax, dsay, dir) \
    ((u_long)(ssax) | ((u_long)(ssay) << 16) | ((u_long)(dsax) << 32) | \
     ((u_long)(dsay) << 48) | ((u_long)(dir) << 59))
#define SCE_GS_SET_TRXDIR(xdir) ((u_long)(xdir))

extern bool nglDisableTim2Conversion;
extern int nglTim2CalcBufWidth(int psm, int width);

__asm__(".equ nglDisableTim2Conversion,0x004BB7F0");
__asm__(".equ nglTim2CalcBufWidth__Fii,0x0039D9F8");

void nglBakeTextureChunk( u_long*& Packet, int psm, int tbw, int w, int h, u_long128 *image )
{
  int line_size;
  switch ( psm )
  {
    case SCE_GS_PSMZ32:
    case SCE_GS_PSMCT32:
      line_size = w * 4;
      break;

    case SCE_GS_PSMZ24:
    case SCE_GS_PSMCT24:
      line_size = w * 3;
      break;

    case SCE_GS_PSMZ16:
    case SCE_GS_PSMZ16S:
    case SCE_GS_PSMCT16:
    case SCE_GS_PSMCT16S:
      line_size = w * 2;

      if ( !nglDisableTim2Conversion )
      {
        psm = SCE_GS_PSMCT32;
        w >>= 1;
        tbw = nglTim2CalcBufWidth(psm,w);
      }
      break;

    case SCE_GS_PSMT8H:
    case SCE_GS_PSMT8:
      line_size = w;

      if ( !nglDisableTim2Conversion )
      {
        psm = SCE_GS_PSMCT32;
        w >>= 1;
        tbw = nglTim2CalcBufWidth(psm,w);
      }
      break;

    case SCE_GS_PSMT4HL:
    case SCE_GS_PSMT4HH:
    case SCE_GS_PSMT4:
      line_size = w / 2;

      if ( !nglDisableTim2Conversion )
      {
        psm = SCE_GS_PSMCT32;
        w >>= 1;
        tbw = nglTim2CalcBufWidth(psm,w);
      }
      break;

    default:
      return;
  }

  int lines = 32764 * 16 / line_size;
  for( int y = 0; y < h; y += lines )
  {
    u_long128* p = (u_long128*)( (char*)image + line_size * y );
    if( y + lines > h )
      lines = h - y;

    int qwc = ( lines * line_size + 15 ) / 16;

    *(Packet++) = SCE_DMA_SET_TAG( 5, 0, SCE_DMA_ID_CNT, 0, 0, 0 );
    *(Packet++) = 0;

    *(Packet++) = SCE_GIF_SET_TAG( 3, 0, 0, 0, 0, 1 );
    *(Packet++) = 0xE;

    *(Packet++) = SCE_GS_SET_TRXREG( w, lines );
    *(Packet++) = SCE_GS_TRXREG;

    *(Packet++) = SCE_GS_SET_TRXPOS( 0, 0, 0, y, 0 );
    *(Packet++) = SCE_GS_TRXPOS;

    *(Packet++) = SCE_GS_SET_TRXDIR( 0 );
    *(Packet++) = SCE_GS_TRXDIR;

    *(Packet++) = SCE_GIF_SET_TAG( qwc, 0, 0, 0, SCE_GIF_IMAGE, 0 );
    *(Packet++) = 0;

    *(Packet++) = SCE_DMA_SET_TAG( qwc, 0, SCE_DMA_ID_REF, 0, p, 0 );
    *(Packet++) = 0;
  }

  *(Packet++) = SCE_DMA_SET_TAG( 0, 0, SCE_DMA_ID_RET, 0, 0, 0 );
  *(Packet++) = 0;
}
